<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket {{ $sale->uuid }}</title><style>@page{size:80mm auto;margin:3mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;color:#111}.ticket{width:74mm;margin:auto;padding:3mm;text-align:center}.brand{font-size:20px;font-weight:700}.meta{font-size:12px;text-align:left;border-top:1px dashed #333;border-bottom:1px dashed #333;padding:8px 0;margin:8px 0}.meta p{margin:4px 0}.qr{margin:8px auto}.qr svg{width:42mm;height:42mm}.reprint{font-weight:700}.actions{margin:12px}.actions button{padding:10px;margin:3px}@media print{.actions{display:none}}</style></head><body><div class="ticket">@if($sale->logs()->where('action','reprint')->exists())<div class="reprint">REPRINT</div>@endif<div class="brand">BookTKIT</div><div>{{ optional($sale->booking->event)->title ?? 'Event Ticket' }}</div><div class="meta"><p><strong>Booking:</strong> {{ $sale->booking->booking_id }}</p><p><strong>Customer:</strong> {{ $sale->booking->fname }}</p><p><strong>Phone:</strong> {{ $sale->booking->phone }}</p>@if($sale->booking->event_date)<p><strong>Event date:</strong> {{ $sale->booking->event_date }}</p>@endif<p><strong>Tickets:</strong> {{ $sale->booking->quantity }}</p><p><strong>Paid:</strong> {{ number_format($sale->customer_total/100,2) }} {{ $sale->currency }}</p><p><strong>Payment:</strong> {{ strtoupper($sale->payment_method) }}</p></div>@foreach($issuedTickets as $ticket)<div><strong>{{ $ticket['ticket_name'] }}</strong></div><div class="qr">{!! QrCode::size(220)->margin(1)->generate($ticket['token']) !!}</div><small>{{ $ticket['uuid'] }}</small>@endforeach<div class="actions"><button onclick="window.print()">Print 58/80mm Ticket</button>@if(auth('organizer')->check())<form method="post" action="{{ route('organizer.boxoffice.reprint',$sale->id) }}">@csrf<button>Log reprint</button></form>@endif</div></div><script>window.addEventListener('load',()=>{if(new URLSearchParams(location.search).get('autoprint')==='1')window.print()})</script></body></html>